          user.dragonfruits,
          DragonFruit,
          createDragonFruits,
          crudConfig,
          userService,
        );
        createEntities(
          em,
          user,
          user.pictures,
          Picture,
          createPictures,
          crudConfig,
          userService,
        );

        return em.flush();
      });
    promises.push(prom);
  }
  await Promise.all(promises);
}

